import { ScrollViewStyleReset } from "expo-router/html";
import type { PropsWithChildren } from "react";

const BOOT_CSS = `#__snhs_boot_loader{position:fixed;inset:0;z-index:9999;display:grid;place-items:center;background:radial-gradient(circle at 50% 41%,rgba(96,165,250,.14),transparent 27%),linear-gradient(150deg,#fbfdff 0%,#f7faff 52%,#edf5ff 100%);transition:opacity .65s ease,transform .7s cubic-bezier(.22,.75,.2,1)}
#__snhs_boot_loader.snhs-exit{opacity:0;transform:translateY(-18px);pointer-events:none}
#__snhs_boot_loader::before{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(59,130,246,.11) 1px,transparent 1px);background-size:25px 25px;mask-image:linear-gradient(to bottom,rgba(0,0,0,.7),transparent 76%)}
.snhs-scene{position:relative;width:min(400px,92vw);height:min(620px,88vh);display:flex;justify-content:center}
.snhs-eyebrow{position:absolute;top:0;display:flex;align-items:center;gap:8px;padding:7px 12px;border:1px solid rgba(59,130,246,.12);border-radius:999px;color:#6b86b8;background:rgba(255,255,255,.68);font-size:9px;font-weight:800;letter-spacing:1.45px;animation:snhsFade .6s .15s ease both}
.snhs-eyebrow i{width:6px;height:6px;border-radius:50%;background:#3b82f6;box-shadow:0 0 0 4px rgba(59,130,246,.1)}
.snhs-cap{position:absolute;top:44px;width:96px;filter:drop-shadow(0 7px 8px rgba(29,78,216,.18));animation:snhsCap .65s .15s cubic-bezier(.18,.85,.25,1.25) both}
.snhs-books{position:absolute;top:122px;width:120px;display:flex;flex-direction:column;align-items:center;gap:5px}
.snhs-book{position:relative;height:22px;border-radius:6px;box-shadow:0 7px 13px rgba(29,78,216,.16);animation:snhsBook .52s cubic-bezier(.2,.8,.3,1.25) both}
.snhs-book::before{content:"";position:absolute;left:12px;width:5px;height:100%;background:rgba(255,255,255,.27)}
.snhs-book:nth-child(1){width:106px;background:#173b8e;animation-delay:.67s}
.snhs-book:nth-child(2){width:99px;background:#3b82f6;animation-delay:.82s}
.snhs-book:nth-child(3){width:92px;background:#60a5fa;animation-delay:.97s}
.snhs-writing{position:absolute;top:200px;width:180px;height:42px}
.snhs-line{position:absolute;left:4px;bottom:7px;width:142px;height:2px;border-radius:2px;background:#3b82f6;transform:scaleX(0);transform-origin:left;animation:snhsLine .68s 1.18s cubic-bezier(.4,0,.2,1) forwards}
.snhs-pencil{position:absolute;top:2px;right:-7px;width:78px;transform:translateX(190px) rotate(-7deg);animation:snhsPencil .68s 1.18s cubic-bezier(.16,.7,.25,1) forwards}
.snhs-logo-wrap{position:absolute;top:248px;width:134px;height:134px;display:grid;place-items:center;padding:14px;border:1px solid rgba(255,255,255,.9);border-radius:50%;background:linear-gradient(145deg,rgba(255,255,255,.98),rgba(235,244,255,.88));box-shadow:inset 0 0 0 7px rgba(59,130,246,.055),inset 0 1px 0 #fff;filter:drop-shadow(0 20px 26px rgba(29,78,216,.24));animation:snhsLogo .78s 1.78s cubic-bezier(.16,.85,.25,1.2) both}
.snhs-logo-wrap::before{content:"";position:absolute;inset:-10px;border:1px solid rgba(59,130,246,.18);border-radius:50%;border-top-color:rgba(59,130,246,.62);border-right-color:rgba(96,165,250,.38);animation:snhsRing 8s linear infinite}
.snhs-logo-wrap img{width:100%;height:100%;object-fit:contain}
.snhs-identity{position:absolute;top:398px;width:96%;text-align:center;animation:snhsCopy .55s 2.32s cubic-bezier(.2,.75,.3,1) both;opacity:0;transform:translateY(10px)}
.snhs-identity h1{margin:0;color:#173b8e;font-size:clamp(24px,7vw,30px);line-height:1.1;letter-spacing:-1px}
.snhs-identity p{margin:10px 0 0;color:#3b82f6;font-size:10px;font-weight:750;letter-spacing:3px}
.snhs-status-wrap{position:absolute;bottom:4px;width:100%;text-align:center}
.snhs-status{min-height:20px;color:#6b86b8;font-size:14px;font-weight:500;animation:snhsFade .5s 2.65s ease both;opacity:0}
.snhs-progress-row{width:min(220px,68vw);display:flex;align-items:center;gap:12px;margin:14px auto 0;animation:snhsFade .5s 2.65s ease both;opacity:0}
.snhs-progress{position:relative;flex:1;height:4px;overflow:hidden;border-radius:4px;background:rgba(59,130,246,.13)}
.snhs-progress-fill{width:8%;height:100%;border-radius:inherit;background:linear-gradient(90deg,#1d4ed8,#60a5fa);transition:width .7s cubic-bezier(.2,.7,.2,1)}
.snhs-percent{width:30px;color:#3b82f6;font-size:10px;font-weight:800}
.snhs-secure{margin-top:12px;color:rgba(107,134,184,.7);font-size:9px;font-weight:700;letter-spacing:.8px;animation:snhsFade .5s 2.65s ease both;opacity:0}
@keyframes snhsCap{0%{opacity:0;transform:translateY(-170px)}75%{opacity:1;transform:translateY(8px)}100%{opacity:1;transform:translateY(0)}}
@keyframes snhsBook{0%{transform:translateX(-220px)}78%{transform:translateX(8px)}100%{transform:translateX(0)}}
@keyframes snhsPencil{from{transform:translateX(190px) rotate(-7deg)}to{transform:translateX(0) rotate(-7deg)}}
@keyframes snhsLine{to{transform:scaleX(1)}}
@keyframes snhsLogo{0%{opacity:0;transform:scale(.8)}64%{opacity:1;transform:scale(1.08)}100%{opacity:1;transform:scale(1)}}
@keyframes snhsCopy{to{opacity:1;transform:translateY(0)}}
@keyframes snhsFade{to{opacity:1}}
@keyframes snhsRing{to{transform:rotate(360deg)}}`;

const BOOT_HTML = `<div class="snhs-scene"><div class="snhs-eyebrow"><i></i>SRI NARAYANA TEACHER TASKS</div><svg class="snhs-cap" viewBox="0 0 104 65"><polygon points="4,23 52,2 100,23 52,44" fill="#1D4ED8"/><path d="M24 32v15c10 11 46 11 56 0V32L52 45z" fill="#2563EB"/><path d="M96 24v22" stroke="#173B8E" stroke-width="3" stroke-linecap="round"/><circle cx="96" cy="50" r="4" fill="#60A5FA"/></svg><div class="snhs-books"><div class="snhs-book"></div><div class="snhs-book"></div><div class="snhs-book"></div></div><div class="snhs-writing"><div class="snhs-line"></div><svg class="snhs-pencil" viewBox="0 0 86 24"><path d="M4 12L13 5h58v14H13z" fill="#FBBF24"/><path d="M4 12l9-7v14z" fill="#F4D3A1"/><path d="M4 12l5-4v8z" fill="#173B8E"/><rect x="70" y="5" width="11" height="14" rx="3" fill="#FB7185"/></svg></div><div class="snhs-logo-wrap"><img src="data:image/png;base64," alt="School logo"/></div><div class="snhs-identity"><h1>Sri Narayana Teacher Tasks</h1><p>EMPOWERING EDUCATORS</p></div><div class="snhs-status-wrap"><div class="snhs-status" id="snhsStatus">Preparing...</div><div class="snhs-progress-row"><div class="snhs-progress"><div class="snhs-progress-fill" id="snhsFill"></div></div><span class="snhs-percent" id="snhsPct">8%</span></div><div class="snhs-secure">SECURE • CONNECTED</div></div></div>`;

const BOOT_JS = `(function(){
var boot=document.getElementById('__snhs_boot_loader');
if(!boot)return;
var msgs=["Preparing Dashboard...","Loading Tasks...","Checking Deadlines...","Almost Ready..."];
var vals=[24,47,68,86,100];
var statusEl=document.getElementById('snhsStatus');
var fill=document.getElementById('snhsFill');
var pct=document.getElementById('snhsPct');
var i=0;
var timer=setInterval(function(){
if(i>=msgs.length){clearInterval(timer);return;}
if(statusEl)statusEl.textContent=msgs[i];
if(fill)fill.style.width=vals[i]+'%';
if(pct)pct.textContent=vals[i]+'%';
i++;
},900);
var done=false;
function hide(){
if(done)return;done=true;clearInterval(timer);
boot.classList.add('snhs-exit');
setTimeout(function(){if(boot.parentNode)boot.parentNode.removeChild(boot);},800);
}
function rootReady(){var r=document.getElementById('root');return r&&r.children.length>0;}
if(rootReady()){setTimeout(hide,1500);}
else{
var r=document.getElementById('root');
if(r){new MutationObserver(function(){if(rootReady())setTimeout(hide,1500);}).observe(r,{childList:true});}
setTimeout(hide,25000);
}
})();`;

export default function Root({ children }: PropsWithChildren) {
  return (
    <html lang="en">
      <head>
        <meta charSet="utf-8" />
        <meta httpEquiv="X-UA-Compatible" content="IE=edge" />
        <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no" />
        <meta name="theme-color" content="#F7FAFF" />
        <title>Sri Narayana Teacher Tasks</title>
        <ScrollViewStyleReset />
        <style dangerouslySetInnerHTML={{ __html: BOOT_CSS }} />
      </head>
      <body>
        <div id="__snhs_boot_loader" dangerouslySetInnerHTML={{ __html: BOOT_HTML }} />
        {children}
        <script dangerouslySetInnerHTML={{ __html: BOOT_JS }} />
      </body>
    </html>
  );
}
